public class RunMeFirstOnce {
    public static String FW_ARGS;

    /* Once per run, before any test case: an empty folder for the generated .feature files, the dummy web shop started
       on a free loopback port, and one headless browser started against it, so Selenium Manager has resolved the driver
       before the parallel test cases ask for one. Every test case receives the shop's URL and the folder. */
    public static void main(String[] args) throws Exception {
        String folder = org.ghyura.cf.showcase.cucumber.GherkinCase.prepareFolder(args.length > 0 ? args[0]
                : "showcase-cucumber/target/generated-features/02-selenium-webshop");
        String url = org.ghyura.cf.showcase.cucumber.web.Bootstrap.startShopAndWarmUp();
        FW_ARGS = url + " " + folder;
    }
}

