import org.ghyura.cf.showcase.cucumber.GherkinCase;

/* webshop_selenium (showcase-cucumber/02-selenium-webshop): every test case is one Gherkin scenario that drives the dummy
   web shop through a headless Firefox. The heart of it is the timeline: the customer's three cart actions in one of their
   6 orders, then paying, with up to two sudden events woven in after any of them (a reload; going back and repeating the
   last action). Selenium Manager resolves the driver by itself and PicoContainer auto-wires the browser into the glue; the
   bootstrap started the shop once for the run and passed its URL. The first failing Then gives the verdict, the
   FW_EXIT_CODE of its own sheet, which FW_CUSTOM_VAR names; a failing Given or When gives 90. */
public class WebshopSeleniumCase {
    public static int FW_VAR = 0;
    static final GherkinCase g = new GherkinCase("Dummy web shop: cart actions in every order, sudden events at every moment",
            "FW_REPLACE_ME_WITH_CURRENT_COMBO_SEQUENCE");

    /* A Then line with the verdict it gives when it fails; its cell hands the sheet's exit code over through FW_VAR. */
    static void then(String text, int code) {
        g.then(text, code);
        FW_VAR = 0;
    }

    public static void main(String[] args) {
        String url = args.length > 0 ? args[0] : "http://127.0.0.1:8080";
        String folder = args.length > 1 ? args[1] : "showcase-cucumber/target/generated-features/02-selenium-webshop";
        g.placeholder("base_url", url);
        g.onStepFailure(90);
        g.fact("reload", "none");
        g.fact("back_repeat", "none");

TAIL:
        GherkinCase.Outcome outcome = g.run(folder, "org.ghyura.cf.showcase.cucumber.webshop");
        FW_VAR = outcome.verdict();
        System.out.println("app=webshop_selenium case=" + g.caseId() + " " + outcome.metricsText() + " FW_VAR=" + FW_VAR);
    }
}
